import test from 'node:test';
import assert from 'node:assert/strict';

import { createClient } from './src/client.mjs';
import { createServer } from './test/server.mjs';

test('ETag-aware cache client', async (t) => {
  const server = createServer();
  const { url } = await server.listen();
  t.after(() => server.close());

  const client = createClient();
  const docUrl = `${url}/doc`;

  // --- First get: a 200 miss -------------------------------------------------
  const first = await client.get(docUrl);
  assert.equal(first.status, 200);
  assert.equal(first.fromCache, false);
  assert.equal(first.body, 'document version 1');

  // --- Second get: 304 -> served from cache ---------------------------------
  const second = await client.get(docUrl);
  assert.equal(second.fromCache, true, 'second get should be served from cache');
  assert.equal(second.body, 'document version 1');

  // The server must have answered 304 to the second request (If-None-Match).
  assert.deepEqual(
    server.requestLog.filter((r) => r.url === '/doc').map((r) => r.status),
    [200, 304],
    'server log should show one 200 followed by one 304',
  );

  // --- Bump then get: new content delivered with a 200 ----------------------
  const bumpRes = await fetch(`${url}/bump`, { method: 'POST' });
  assert.ok(bumpRes.ok);

  const third = await client.get(docUrl);
  assert.equal(third.status, 200);
  assert.equal(third.fromCache, false, 'changed content must not come from cache');
  assert.equal(third.body, 'document version 2');

  // A further get is again a 304 cache hit against the new ETag.
  const fourth = await client.get(docUrl);
  assert.equal(fourth.fromCache, true);
  assert.equal(fourth.body, 'document version 2');

  // Full request-log check for /doc: 200, 304, 200, 304.
  assert.deepEqual(
    server.requestLog.filter((r) => r.url === '/doc').map((r) => r.status),
    [200, 304, 200, 304],
  );
});

