import { createClient } from './src/client.mjs';
import assert from 'node:assert/strict';

/**
 * Create an ETag-aware HTTP cache client.
 *
 * get(url) returns a promise resolving to:
 *   {
 *     status:     HTTP status of the response (200, 304, ...)
 *     body:       response body (from network on 200, from cache on 304)
 *     etag:       the ETag associated with the body
 *     fromCache:  true when the body was served from the local cache
 *   }
 */
export function createClient() {
  /** @type {Map<string, { etag: string, body: string }>} */
  const cache = new Map();

  async function get(url) {
    const entry = cache.get(url);
    const headers = {};
    if (entry) {
      headers['If-None-Match'] = entry.etag;
    }

    const res = await fetch(url, { headers });

    if (res.status === 304 && entry) {
      // Not modified: the cached body is still valid.
      return {
        status: 304,
        body: entry.body,
        etag: entry.etag,
        fromCache: true,
      };
    }

    if (res.ok) {
      const body = await res.text();
      const etag = res.headers.get('etag');
      cache.set(url, { etag, body });
      return { status: res.status, body, etag, fromCache: false };
    }

    throw new Error(`Unexpected status ${res.status} for ${url}`);
  }

  return {
    get,
    clear() {
      cache.clear();
    },
  };
}

// Self-check when run directly.
if (import.meta.url === `file://${process.argv[1]}`) {
  assert.equal(typeof createClient().get, 'function');
  console.log('client ok');
}

