import http from 'node:http';

let docVersionCounter = 0;

function contentFor(version) {
  return `document version ${version}`;
}

/**
 * Test server:
 *  - GET  /doc   -> current document with ETag derived from the version;
 *                   answers 304 (empty body) when If-None-Match matches.
 *  - POST /bump  -> changes the content (increments the version).
 *
 * Every handled request is recorded in `server.requestLog`
 * as { method, url, status } so tests can distinguish 200s from 304s.
 */
export function createServer() {
  let version = ++docVersionCounter;

  /** @type {{ method: string, url: string, status: number }[]} */
  const requestLog = [];

  const server = http.createServer((req, res) => {
    const record = (status) => {
      requestLog.push({ method: req.method, url: req.url, status });
    };

    if (req.method === 'GET' && req.url === '/doc') {
      const etag = `"v${version}"`;
      const inm = req.headers['if-none-match'];

      if (inm && inm === etag) {
        record(304);
        res.writeHead(304, { ETag: etag });
        res.end();
        return;
      }

      record(200);
      res.writeHead(200, {
        'Content-Type': 'text/plain; charset=utf-8',
        ETag: etag,
      });
      res.end(contentFor(version));
      return;
    }

    if (req.method === 'POST' && req.url === '/bump') {
      version += 1;
      record(200);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ version }));
      return;
    }

    record(404);
    res.writeHead(404);
    res.end('not found');
  });

  return {
    server,
    requestLog,

    listen() {
      return new Promise((resolve, reject) => {
        server.once('error', reject);
        // Port 0 -> ephemeral port.
        server.listen(0, '127.0.0.1', () => {
          const { port } = server.address();
          resolve({ url: `http://127.0.0.1:${port}`, port });
        });
      });
    },

    close() {
      return new Promise((resolve, reject) => {
        server.close((err) => (err ? reject(err) : resolve()));
      });
    },
  };
}

